import { test, expect } from '../fixtures/test';

// Reuse the authenticated session generated by globalSetup.
test.use({ storageState: 'auth/user.json' });

test('user can transfer funds', async ({ page, transferPage }) => {
  // Open ParaBank using the saved authenticated session.
  await page.goto('https://parabank.parasoft.com/parabank/', {
    waitUntil: 'domcontentloaded',
  });

  // Confirm that the user is logged in.
  await expect(
    page.getByRole('link', { name: 'Log Out' })
  ).toBeVisible();

  // Create a second account so that a transfer is possible.
  await page.locator('#leftPanel')
    .getByRole('link', { name: 'Open New Account' })
    .click();

  const accountType = page.getByRole('combobox').nth(0);
  const fundingAccount = page.getByRole('combobox').nth(1);

  await accountType.selectOption({ index: 1 });
  await fundingAccount.selectOption({ index: 0 });

  await page.getByRole('button', { name: 'Open New Account' }).click();

  // Verify that the second account was created.
  await expect(
    page.getByText('Congratulations, your account is now open.')
  ).toBeVisible({ timeout: 15000 });

  // Navigate to the transfer page using our custom fixture.
  await transferPage.goto();

  // Wait for the second account to appear in both dropdowns.
  await expect(
    transferPage.fromAccount.locator('option').nth(1)
  ).toBeAttached({ timeout: 15000 });

  await expect(
    transferPage.toAccount.locator('option').nth(1)
  ).toBeAttached({ timeout: 15000 });

  // Retrieve the available account IDs.
  const accounts = await transferPage.fromAccount.locator('option')
    .evaluateAll(options =>
      options.map(option => (option as HTMLOptionElement).value)
    );

  const fromAccount = accounts[0];
  const toAccount = accounts.find(account => account !== fromAccount);

  if (!toAccount) {
    throw new Error('A different destination account was not found.');
  }

  // Transfer $10 between the two accounts.
  await transferPage.transfer('10', fromAccount, toAccount);

  // Verify that the transfer was completed.
  await expect(
    page.getByText('Transfer Complete!')
  ).toBeVisible();
});